arguments.file_text:
namespace sv_5ed76096b91341f197bf51fb206ac964.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped per circuit — each user gets independent theme state that
/// persists across enhanced navigations for the lifetime of the circuit.
/// </summary>
public sealed class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }

    public void ApplyAll(ThemeMode theme, string accentColor)
    {
        var changed = Theme != theme || AccentColor != accentColor;
        Theme = theme;
        AccentColor = accentColor;
        if (changed) OnChange?.Invoke();
    }
}

// Applies the theme to the DOM and persists it in a cookie.
export function applyTheme(theme, accentColor) {
    const root = document.documentElement;
    root.setAttribute('data-bs-theme', resolveTheme(theme));
    root.style.setProperty('--app-accent-color', accentColor);
    setCookie('app-theme', theme, 365);
    setCookie('app-accent', accentColor, 365);
}

export function getStoredTheme() {
    return getCookie('app-theme') || 'System';
}

export function getStoredAccent() {
    return getCookie('app-accent') || '#0d6efd';
}

function resolveTheme(theme) {
    if (theme === 'System') {
        return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }
    return theme.toLowerCase();
}

function setCookie(name, value, days) {
    const d = new Date();
    d.setTime(d.getTime() + days * 86400000);
    document.cookie = `${name}=${encodeURIComponent(value)};expires=${d.toUTCString()};path=/;SameSite=Lax`;
}

function getCookie(name) {
    const v = document.cookie.match('(^|;)\\s*' + name + '\\s*=\\s*([^;]+)');
    return v ? decodeURIComponent(v.pop()) : null;
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

<span class="badge rounded-pill" style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeIcon @ThemeService.Theme
</span>

@code {
    private IJSObjectReference? _module;

    private string ThemeIcon => ThemeService.Theme switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/theme.js");

            // Hydrate service from stored cookie values on first load
            var storedTheme = await _module.InvokeAsync<string>("getStoredTheme");
            var storedAccent = await _module.InvokeAsync<string>("getStoredAccent");

            if (Enum.TryParse<ThemeMode>(storedTheme, true, out var mode))
            {
                ThemeService.ApplyAll(mode, storedAccent);
            }

            await _module.InvokeVoidAsync("applyTheme",
                ThemeService.Theme.ToString(), ThemeService.AccentColor);
        }
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(async () =>
        {
            if (_module is not null)
            {
                await _module.InvokeVoidAsync("applyTheme",
                    ThemeService.Theme.ToString(), ThemeService.AccentColor);
            }
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<div class="nav-item px-3">
    <button class="btn btn-sm btn-outline-light w-100" @onclick="CycleTheme">
        @ThemeIcon @ThemeService.Theme Mode
    </button>
</div>

@code {
    private string ThemeIcon => ThemeService.Theme switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChanged;
    }

