@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <button type="button"
                        class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-secondary")"
                        @onclick="() => ThemeService.SetTheme(mode)">
                    @mode
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentChanged" />
            <span class="badge rounded-pill" style="background-color: @ThemeService.AccentColor; color: white;">
                @ThemeService.AccentColor
            </span>
        </div>

        <h5 class="card-title">Preview</h5>
        <p>
            Current theme: <strong>@ThemeService.Theme</strong><br />
            Accent color: <strong style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</strong>
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        if (e.Value is string color && !string.IsNullOrWhiteSpace(color))
        {
            ThemeService.SetAccentColor(color);
        }
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChanged;
    }
}

